async function capture(name,locator=page) { await page.evaluate(async()=>{document.activeElement?.blur();scrollTo(0,0);await document.fonts.ready;await new Promise(resolve=>requestAnimationFrame(()=>requestAnimationFrame(resolve)));});const file=path.join(media,name+'.png');await locator.screenshot({path:file,animations:'disabled',...(locator===page?{fullPage:false}:{})});screenshots.push(file); }
